def solve_demo(grid):
    H,W=len(grid),len(grid[0])
    rows=[r for r in range(H) if all(v==0 for v in grid[r])]
    cols=[c for c in range(W) if all(grid[r][c]==0 for r in range(H))]
    def segs(seps,n):
        res=[];prev=0
        for s in seps:
            if s>prev: res.append((prev,s))
            prev=s+1
        if n>prev: res.append((prev,n))
        return res
    R=segs(rows,H); C=segs(cols,W)
    out=[]
    for r0,r1 in R:
        row=[]
        for c0,c1 in C:
            has8=any(grid[r][c]==8 for r in range(r0,r1) for c in range(c0,c1))
            row.append(1 if has8 else 5)
        out.append(row)
    return out
